// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp) public {
        // Ensure timestamp is in the future for the first call
        vm.assume(timestamp > block.timestamp);

        // Advance time to the given timestamp
        vm.warp(timestamp);

        // First call: should succeed
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        assertTrue(success1);

        // Second call at the same timestamp (same block)
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // The reference contract must revert because block.timestamp == pastBlockTime
        // The mutant will succeed because it deletes the check
        assertTrue(!success2);
    }
}

